// src/document-parser/document-parser.controller.ts
import { Controller, Post, Body, Headers, HttpException, HttpStatus } from '@nestjs/common';
import { DocumentParserService } from './document-parser.service';
import { ApiTags, ApiOperation } from '@nestjs/swagger';

@ApiTags('documents')
@Controller('api/v2/documents')
export class DocumentParserController {
  constructor(private readonly parserService: DocumentParserService) {}

  @Post('parse')
  @ApiOperation({ summary: 'Parse XML document and extract metadata' })
  async parseDocument(
    @Body() body: { content: string; format: string },
    @Headers('x-correlation-id') correlationId: string,
  ) {
    if (!body.content || !body.format) {
      throw new HttpException('Missing required fields', HttpStatus.BAD_REQUEST);
    }

    if (body.format !== 'xml' && body.format !== 'svg' && body.format !== 'xhtml') {
      throw new HttpException('Unsupported format', HttpStatus.UNPROCESSABLE_ENTITY);
    }

    try {
      const result = await this.parserService.parseXmlContent(
        body.content,
        correlationId,
      );
      return { status: 'success', data: result, correlationId };
    } catch (error) {
      throw new HttpException(
        { message: 'Parse error', detail: error.message },
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }
}

