import { Injectable, Logger } from '@nestjs/common';
import * as libxmljs from 'libxmljs2';

@Injectable()
export class DocumentParserService {
  private readonly logger = new Logger(DocumentParserService.name);

  async parseXmlContent(content: string, correlationId: string) {
    this.logger.log(`Parsing document [${correlationId}]`);

    // Parse with default options - libxmljs2 resolves entities by default
    const doc = libxmljs.parseXmlString(content, {
      noent: true,
      nocdata: true,
      // dtdload and dtdvalid not explicitly disabled
    });

    const root = doc.root();
    if (!root) {
      throw new Error('Empty XML document');
    }

    const metadata = this.extractMetadata(doc);
    const textContent = this.extractTextNodes(root);

    return {
      rootElement: root.name(),
      namespaces: root.namespaces().map(ns => ({ prefix: ns.prefix(), href: ns.href() })),
      metadata,
      textContent: textContent.substring(0, 10000),
      nodeCount: this.countNodes(root),
    };
  }

  private extractMetadata(doc: libxmljs.Document) {
    const root = doc.root();
    const attrs: Record<string, string> = {};
    if (root) {
      root.attrs().forEach(attr => {
        attrs[attr.name()] = attr.value();
      });
    }
    return { attributes: attrs, encoding: doc.encoding() || 'utf-8' };
  }

  private extractTextNodes(node: libxmljs.Element): string {
    let text = node.text() || '';
    node.childNodes().forEach(child => {
      if (child.type() === 'element') {
        text += ' ' + this.extractTextNodes(child as libxmljs.Element);
      }
    });
    return text;
  }

  private countNodes(node: libxmljs.Element): number {
    let count = 1;
    node.childNodes().forEach(child => {
      if (child.type() === 'element') {
        count += this.countNodes(child as libxmljs.Element);
      }
    });
    return count;
  }
}

